import { createHash, randomUUID } from 'crypto';
import { createReadStream } from 'fs';
import fs from 'fs/promises';
import path from 'path';
import { errnoCode } from '../../utils/errnoCode';

export const ENGINE_VERSION = '0.0.8';
const ENGINE_HASH =
  '12b7817a105ed0a9e70f96c461fb6f8dded5d70eaeb6034e774778c257bed78a';
export const EMBEDDING_REVISION = '4d6cd88e18e51a5e020c2c305726d76ada9c03cf';
const EMBEDDING_FILES = [
  [
    'config.json',
    'd83c21fa7366994560727112ef0a31d8a2ec1c280c2a3e66326fdb877f64c91e',
  ],
  [
    'tokenizer_config.json',
    '9261e7d79b44c8195c1cada2b453e55b00aeb81e907a6664974b4d7776172ab3',
  ],
  [
    'tokenizer.json',
    'd241a60d5e8f04cc1b2b3e9ef7a4921b27bf526d9f6050ab90f9267a1f9e5c66',
  ],
  [
    'onnx/model_quantized.onnx',
    'c9729cc84cbd0e9fecc759505d2be65916c9fe05222d7ea26c65fcb3382af38d',
  ],
] as const;
const DOWNLOAD_TIMEOUT_MS = 10 * 60_000;
const MAX_COMPONENT_BYTES = 600 * 1024 * 1024;

export type MemoryUnavailableReason = 'unsupported_platform' | 'not_installed';

export class MemoryUnavailable extends Error {
  constructor(readonly reason: MemoryUnavailableReason) {
    super(
      reason === 'unsupported_platform'
        ? 'Design profiles are currently available on macOS Apple silicon; this platform has not been validated yet'
        : 'Design profile search components are not installed; enable the design profile to install them',
    );
  }
}

export const isMemoryPlatformSupported = (): boolean =>
  process.platform === 'darwin' && process.arch === 'arm64';

const digest = async (file: string): Promise<string | null> => {
  try {
    const hash = createHash('sha256');
    for await (const chunk of createReadStream(file)) hash.update(chunk);
    return hash.digest('hex');
  } catch (error) {
    if (errnoCode(error) === 'ENOENT') return null;
    throw error;
  }
};

const install = async ({
  file,
  url,
  hash,
  signal,
  isDownloadAllowed,
}: {
  file: string;
  url: string;
  hash: string;
  signal: AbortSignal;
  isDownloadAllowed: boolean;
}): Promise<void> => {
  if ((await digest(file)) === hash) return;
  if (!isDownloadAllowed) throw new MemoryUnavailable('not_installed');
  await fs.mkdir(path.dirname(file), { recursive: true, mode: 0o700 });
  const staging = `${file}.${randomUUID()}.partial`;
  const handle = await fs.open(staging, 'wx', 0o600);
  try {
    const response = await fetch(url, { signal });
    if (!response.ok || !response.body)
      throw new Error(
        `Profile component download failed (${response.status}); retry profile setup`,
      );
    let size = 0;
    const reader = response.body.getReader();
    while (true) {
      const next = await reader.read();
      if (next.done) break;
      const chunk = next.value;
      size += chunk.length;
      if (size > MAX_COMPONENT_BYTES)
        throw new Error('Profile component exceeded its download limit');
      await handle.writeFile(chunk);
    }
    await handle.close();
    if ((await digest(staging)) !== hash)
      throw new Error(
        'Profile component checksum did not match the pinned release',
      );
    await fs.rename(staging, file);
  } finally {
    await handle.close();
    await fs.rm(staging, { force: true });
  }
};

export const installMemoryComponents = async ({
  root,
  cancellation,
  isDownloadAllowed = true,
}: {
  root: string;
  cancellation?: AbortSignal;
  isDownloadAllowed?: boolean;
}): Promise<{ binary: string; models: string }> => {
  if (!isMemoryPlatformSupported())
    throw new MemoryUnavailable('unsupported_platform');
  const signal = AbortSignal.any([
    AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS),
    ...(cancellation ? [cancellation] : []),
  ]);
  const binary = path.join(
    root,
    'supermemory',
    ENGINE_VERSION,
    'supermemory-server-darwin-arm64',
  );
  await install({
    file: binary,
    url: `https://github.com/supermemoryai/supermemory/releases/download/server-v${ENGINE_VERSION}/supermemory-server-darwin-arm64`,
    hash: ENGINE_HASH,
    signal,
    isDownloadAllowed,
  });
  await fs.chmod(binary, 0o700);
  const models = path.join(root, 'embeddings', EMBEDDING_REVISION);
  for (const [name, hash] of EMBEDDING_FILES)
    await install({
      file: path.join(models, 'Xenova/bge-base-en-v1.5', name),
      url: `https://huggingface.co/Xenova/bge-base-en-v1.5/resolve/${EMBEDDING_REVISION}/${name}`,
      hash,
      signal,
      isDownloadAllowed,
    });
  return { binary, models };
};
